//----------------------------------------------------------------------------------------// Global assembly inline function definitions.//----------------------------------------------------------------------------------------#if !qPowerPC && !qMSWindows#ifdef __MWERKS__	#pragma d0_pointers on#endiflong GetParmBlockPtr() = {0x2008};				// MOVE.L A0,D0												// Return the value of register A0.												// Useful for getting the pointer												// to the parameter block from a												// VBL task or a completion routine.long GetA5() = {0x200D};						// MOVE.L A5,D0												// Return the value of register A5.												// Useful for getting the immediate												// value of A5 which is not always												// the same as CurrentA5.  Generally												// a pointer to the program's global												// area and jump table.	#if qDebugPtr GetCurStackFramePtr() = {0x200E};			// MOVE.L A6,D0												// Return the value of register A6.												// Usually a pointer to the local												// stack frame.  Most often used to												// find out the caller's name when												// invoking a debugging routine.	Ptr GetCurStackTop() = {0x200F};				// MOVE.L A7,D0												// Return the value of register A7.												// Usually the top of the stack.												// Useful for stack sniffing (not												// a crime).#endif#ifdef __MWERKS__	#pragma d0_pointers reset#endif#endif//----------------------------------------------------------------------------------------// Global function declarations that need to always be compiled for 68000.//----------------------------------------------------------------------------------------#if	!qMSWindows && !qCarbonEXPORT_MA TrapType GetTrapType(short theTrap);#endifEXPORT_MA bool TrapExists(short theTrap);//----------------------------------------------------------------------------------------// Global function declarations//--------------------------